G=load()
from collections import Counter
def f(g):
    bg=Counter(c for r in g for c in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    w=len(g[0])
    for i in range(len(g)):
        for j in range(w):
            if g[i][j]!=bg:
                out[i][w-1-j]=g[i][j]
    return out
